using Microsoft.EntityFrameworkCore;
namespace FacciStats;
public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options) { public DbSet<Personaje> Personajes => Set<Personaje>(); public DbSet<Carta> Cartas => Set<Carta>(); public DbSet<Evento> Eventos => Set<Evento>(); public DbSet<Usuario> Usuarios => Set<Usuario>(); protected override void OnModelCreating(ModelBuilder b) { b.Entity<Personaje>(e => { e.Property(x => x.Nombre).HasMaxLength(100).IsRequired(); e.Property(x => x.Faccion).HasMaxLength(80).IsRequired(); e.Property(x => x.BiografiaSecreta).HasMaxLength(2000); }); b.Entity<Carta>(e => { e.Property(x => x.Nombre).HasMaxLength(100).IsRequired(); e.HasOne(x => x.Personaje).WithMany(x => x.Cartas).HasForeignKey(x => x.PersonajeId).OnDelete(DeleteBehavior.Restrict); }); b.Entity<Evento>(e => { e.Property(x => x.Nombre).HasMaxLength(120).IsRequired(); e.Property(x => x.FaccionGanadora).HasMaxLength(80).IsRequired(); }); b.Entity<Usuario>(e => { e.Property(x => x.Email).HasMaxLength(150).IsRequired(); e.HasIndex(x => x.Email).IsUnique(); e.Property(x => x.PasswordHash).HasMaxLength(255).IsRequired(); e.Property(x => x.Telefono).HasMaxLength(255); }); } }
